using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new GroundednessEvaluator(),
            ]);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.StopAsync();
        await _appHost.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_ReturnsCoherentResponse()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France? Answer in one sentence.")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ReturnsCoherentResponse));

        scenario.Record(
            messages,
            response,
            additionalContext: [new EvaluationContext("grounding", "The capital of France is Paris.")]);

        var metrics = scenario.GetAllMetrics();
        foreach (var metric in metrics)
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Identifier}' scored {numericMetric.Value}, expected >= 3");
            }
        }
    }

    [TestMethod]
    public async Task Chat_FollowsInstructions()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that always responds in exactly three bullet points."),
            new(ChatRole.User, "What are the benefits of exercise?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_FollowsInstructions));

        scenario.Record(messages, response);

        var metrics = scenario.GetAllMetrics();
        foreach (var metric in metrics)
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Identifier}' scored {numericMetric.Value}, expected >= 3");
            }
        }

        var text = response.Text ?? string.Empty;
        var bulletCount = text.Split('\n', StringSplitOptions.RemoveEmptyEntries)
            .Count(line => line.TrimStart().StartsWith("- ") || line.TrimStart().StartsWith("* ") || line.TrimStart().StartsWith("• "));
        Assert.IsTrue(bulletCount >= 3, $"Expected at least 3 bullet points, got {bulletCount}");
    }

    [TestMethod]
    public async Task Chat_HandlesMultiTurnConversation()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice."),
        };

        var firstResponse = await _chatClient.GetResponseAsync(messages);
        messages.Add(new ChatMessage(ChatRole.Assistant, firstResponse.Text));
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var response = await _chatClient.GetResponseAsync(messages);

        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_HandlesMultiTurnConversation));

        scenario.Record(
            messages,
            response,
            additionalContext: [new EvaluationContext("grounding", "The user's name is Alice.")]);

        var metrics = scenario.GetAllMetrics();
        foreach (var metric in metrics)
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Identifier}' scored {numericMetric.Value}, expected >= 3");
            }
        }

        Assert.IsTrue(
            response.Text?.Contains("Alice", StringComparison.OrdinalIgnoreCase) == true,
            "Expected the response to remember the user's name 'Alice'");
    }
}

